import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            long v = sc.nextLong();
            // A power of two has exactly one set bit, so v & (v - 1) clears it to 0.
            if (i > 0) sb.append(' ');
            sb.append(v > 0 && (v & (v - 1)) == 0 ? 1 : 0);
        }
        System.out.println(sb);
    }
}

